public class Main {
  static int total(int price, int count) {
    if (price < 0 || count < 0) throw new IllegalArgumentException("negative input");
    return Math.multiplyExact(price, count);
  }
  public static void main(String[] args) {
    if (total(125, 4) != 500) throw new AssertionError("regular case");
    if (total(125, 0) != 0) throw new AssertionError("empty case");
    try { total(-1, 2); throw new AssertionError("missing error"); }
    catch (IllegalArgumentException expected) { System.out.println("ok"); }
  }
}

import java.util.*;
public class Main {
  record Entry(String title, int minutes) {
    Entry { if (title == null || title.isBlank() || minutes <= 0) throw new IllegalArgumentException("bad entry"); }
  }
  public static void main(String[] args) {
    var entries = new ArrayList<Entry>();
    entries.add(new Entry("Walk", 30));
    System.out.println(entries.stream().mapToInt(Entry::minutes).sum());
  }
}

package main
import ("context"; "fmt"; "time")
func wait(ctx context.Context) error {
  select { case <-time.After(50*time.Millisecond): return nil; case <-ctx.Done(): return ctx.Err() }
}
func main() { ctx, cancel := context.WithTimeout(context.Background(), time.Millisecond); defer cancel(); fmt.Println(wait(ctx) != nil) }

